select s.country, case when s.rating >= 3.7 then 'high' when s.rating >= 2.2 then 'mid' else 'low' end as rating_bucket, count(case when p.brand = 'Umbrella' then 1 end) as umbrella_count, sort_array(collect_set(p.category)) as category_list from products p left join suppliers s on p.supplier_id = s.id where p.supplier_id = 38 group by s.country, case when s.rating >= 3.7 then 'high' when s.rating >= 2.2 then 'mid' else 'low' end order by umbrella_count desc, rating_bucket;
